<?php
namespace App\Exports;use App\Models\TransportService;use Maatwebsite\Excel\Concerns\{FromCollection,WithHeadings,WithMapping};
class TransportProgrammingExport implements FromCollection,WithHeadings,WithMapping{public function __construct(private int$company,private array$filters){}public function collection(){$q=TransportService::forCompany($this->company)->with(['vehicle','driver.employee','monitor.employee','passengers'])->orderBy('scheduled_start_at');if($this->filters['from']??null)$q->whereDate('service_date','>=',$this->filters['from']);if($this->filters['to']??null)$q->whereDate('service_date','<=',$this->filters['to']);foreach(['transport_route_id','planned_vehicle_id','planned_driver_id','status']as$f)if($this->filters[$f]??null)$q->where($f,$this->filters[$f]);return$q->get();}public function headings():array{return['Fecha','Hora salida','Llegada prevista','Ruta','Tipo','Jornada','Vehículo','Conductor','Monitor','Pasajeros esperados','Capacidad','Estado'];}public function map($s):array{return[$s->service_date->format('d/m/Y'),$s->scheduled_start_at->format('H:i'),$s->scheduled_arrival_at->format('d/m/Y H:i'),$s->route_name_snapshot,config('transport.service_types.'.$s->service_type),config('transport.shifts.'.$s->shift),$s->vehicle?->plate,$s->driver?->display_name,$s->monitor?->display_name,$s->passengers->where('status','expected')->count(),$s->vehicle?->capacity,config('transport.service_statuses.'.$s->status)];}}
